const rounds = [
  { title: 'Coding & algorithms', interviewer: 'Maya Chen', role: 'Senior Software Engineer', duration: 45, prompt: 'You are given a stream of purchase events. How would you return the first event that makes a customer exceed their monthly spend limit — efficiently, even when there are millions of events?', follow: 'Good starting point. What changes if corrections can arrive out of order, and how would you make the result explainable to an operator?', code: '// Sketch your approach here\nfunction firstOverLimit(events, limit) {\n  // your implementation\n}' },
  { title: 'Systems reasoning', interviewer: 'Jon Bell', role: 'Staff Platform Engineer', duration: 45, prompt: 'Design a service that surfaces a user\'s ten most relevant saved items in under 150ms at p99. Start by clarifying the constraints you need.', follow: 'Let\'s assume 80 million users, high read traffic, and eventual consistency is acceptable. Where do you cache, and what do you measure?', code: '// Draw out APIs, data flow, and tradeoffs\nGET /v1/saved-items?user_id=…' },
  { title: 'Technical collaboration', interviewer: 'Aisha Patel', role: 'Engineering Manager', duration: 30, prompt: 'Tell me about a technically difficult decision you changed your mind about. How did you discover the original approach was wrong, and how did you bring the team along?', follow: 'What was the specific signal that gave you confidence to reverse course? How would you handle a teammate who disagreed?', code: '// Optional: capture metrics, tradeoffs, or a timeline\n' }
];
let state = { view: 'home', company: 'Stripe', role: 'Backend engineer', level: 'Mid-level', round: 0, followUp: false, seconds: 45*60, mic: false, answers: [] };
let timer;
const app = document.querySelector('#app');

function shell(content){return `<div class="shell"><header class="topbar"><div class="brand"><b class="brand-mark">↗</b> Interview Loop</div><nav><a href="#" data-action="home">Practice</a><a href="#sources" data-action="sources">Question intelligence</a><a href="#">Progress</a></nav><div class="profile"><span>Alex R.</span><i class="avatar"></i></div></header>${content}</div>`}
function home(){clearInterval(timer);app.innerHTML=shell(`<section class="hero"><div><div class="eyebrow">Technical interview simulator</div><h1>Practice the <em>real</em> conversation.</h1><p class="hero-copy">A focused virtual onsite for the company and role you care about. Think aloud, write code, handle follow-ups, and leave with a useful debrief.</p></div><aside class="loop-card"><div class="mini-head"><span>YOUR NEXT LOOP</span><span class="live-dot">● 3 live rounds</span></div><div class="persona-row"><div class="persona"><i class="face"></i>Maya<br>Algorithms</div><div class="persona"><i class="face"></i>Jon<br>Systems</div><div class="persona"><i class="face"></i>Aisha<br>Collaboration</div></div><h3>Built to feel like a virtual onsite.</h3><p>Conversational personas, a shared workspace, focused timers, and responsive follow-up questions.</p></aside></section><section class="dashboard-grid"><div class="panel"><h2>Set your practice loop</h2><p>Choose the context. You can start with the thoughtfully curated defaults.</p><div class="form-row"><div class="field"><label>Company</label><select id="company"><option>Stripe</option><option>Google</option><option>Cloudflare</option><option>General technical</option></select></div><div class="field"><label>Target role</label><select id="role"><option>Backend engineer</option><option>Frontend engineer</option><option>Product engineer</option><option>Data engineer</option></select></div><div class="field"><label>Level</label><select id="level"><option>Mid-level</option><option>Senior</option><option>Staff</option><option>New grad</option></select></div><div class="field"><label>Session style</label><div class="format-pills"><button class="format on">Full loop</button><button class="format">One round</button></div></div></div><button class="primary" data-action="start">Start virtual onsite <span>→</span></button><div class="callout"><span>✦</span><span><strong>Graceful by default.</strong> This demo runs in text mode; enable live audio/video with your own AI and voice provider keys.</span></div></div><div class="panel"><h2>Today’s loop</h2><p>Three rounds • 120 minutes • tailored for a ${state.role}.</p><div class="rounds">${rounds.map((r,i)=>`<div class="round"><span class="round-no">0${i+1}</span><div><strong>${r.title}</strong><small>${r.interviewer} · ${r.role}</small></div><time>${r.duration}m</time></div>`).join('')}</div></div></section><section class="source-strip"><div><strong>Question intelligence, not question dumps.</strong><br><span>Public candidate reports and role patterns are normalized, dated, and attributed — never presented as confidential ground truth.</span></div><button class="ghost" data-action="sources">View sourcing policy →</button></section>`);}
function interviewer(){let r=rounds[state.round], mins=String(Math.floor(state.seconds/60)).padStart(2,'0'), secs=String(state.seconds%60).padStart(2,'0');return shell(`<section class="interview"><aside class="side"><div class="session-label">VIRTUAL ONSITE · ROUND ${state.round+1}/3</div><div class="timer ${state.seconds<300?'warn':''}">${mins}:${secs}</div><button class="ghost" data-action="end">End session</button><div class="round-list">${rounds.map((x,i)=>`<div class="round-step ${i===state.round?'active':i<state.round?'done':''}"><i class="step-dot"></i><span><b>${x.title}</b><br>${x.duration} min</span></div>`).join('')}</div><div class="integration-box">LIVE AI READY<br>Set <b>OPENAI_API_KEY</b> and a voice provider key in your server environment to replace the text-mode interviewer.</div></aside><main class="interview-main"><div class="interview-head"><span class="crumb">${state.company} / ${state.role} / ${state.level}</span><span class="connection"><i></i> text-mode connection</span></div><section class="stage"><div class="stage-bar"><span>▣ INTERVIEW ROOM</span><span class="record">● REC</span></div><div class="video-area"><div class="interviewer"><i class="big-face"></i><h2>${r.interviewer}</h2><span>${r.role}</span><div class="waves"><b></b><b></b><b></b><b></b><b></b></div></div><div class="you-tile">You · camera preview</div></div><div class="question"><div class="speaker">${r.interviewer.toUpperCase()} ${state.followUp?'· FOLLOW-UP':''}</div><p>${state.followUp?r.follow:r.prompt}</p></div></section><section class="work-area"><div class="response"><div class="response-head"><b>Your response</b><button class="icon-btn ${state.mic?'listening':''}" data-action="mic" aria-label="toggle microphone">${state.mic?'●':'♩'}</button></div><textarea id="answer" placeholder="Talk through your thinking here. The interviewer will respond to the direction you take…">${state.answers[state.round]||''}</textarea></div><div class="editor"><div class="editor-head"><b>Shared workspace</b><span>JavaScript</span></div><textarea id="code" spellcheck="false">${r.code}</textarea></div></section><div class="actions"><span class="fallback">${state.mic?'Listening locally — text is your transcript fallback.':'Prefer speaking? Use the mic; you can always type.'}</span><button class="primary" data-action="respond">${state.followUp?(state.round===2?'Finish loop':'Continue to next round'):'Send response →'}</button></div></main></section>`)}
function report(){clearInterval(timer);const quality=state.answers.reduce((n,a)=>n+(a||'').length,0);const bonus=quality>350?5:quality>130?2:0;return shell(`<main class="report-wrap"><section class="report-hero"><div><div class="eyebrow">Loop complete · ${state.company}</div><h1>Clearer next time.</h1><p class="hero-copy">A focused readout of your reasoning, communication, and technical execution.</p></div><div class="score">${78+bonus}<small>/100 readiness</small></div></section><section class="score-grid"><article class="scorecard"><h3>Interview signal</h3>${[['Problem framing',86+bonus],['Technical depth',76+bonus],['Communication',82+bonus],['Tradeoff awareness',71+bonus]].map(([n,v])=>`<div class="meter"><div class="meter-top"><b>${n}</b><span>${v}</span></div><div class="bar"><i style="width:${v}%"></i></div></div>`).join('')}</article><article class="scorecard"><h3>Coach’s notes</h3><ul class="feedback"><li><b>Strong:</b> You started by naming constraints before selecting an approach, which kept the coding discussion grounded.</li><li><b>Try next:</b> Make your cache invalidation and failure behavior explicit before the interviewer asks.</li><li><b>Practice:</b> End behavioral stories with the concrete technical outcome and the learning you carried forward.</li></ul></article></section><section class="next-box"><h3>Your targeted next rep</h3><p>Repeat the systems round with stricter latency constraints, then compare your tradeoffs side by side.</p><button class="primary" data-action="restart">Practice another loop →</button> <button class="ghost" data-action="sources">Review question provenance</button></section></main>`)}
function sources(){app.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="close"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><div class="eyebrow">Question intelligence</div><h2>Public-signal sourcing pipeline</h2></div><button class="icon-btn" data-action="close">×</button></div><p>Questions are generated from skill patterns and publicly accessible candidate discussions. Each input keeps its link, retrieval date, role tags, and a confidence signal; the live model paraphrases rather than reproduces source text.</p><div class="source-item"><strong>Public GitHub repositories & issues</strong><div class="tags"><span class="tag">public only</span><span class="tag">attribution retained</span><span class="tag safe">high confidence when corroborated</span></div></div><div class="source-item"><strong>Public Reddit discussions & company engineering material</strong><div class="tags"><span class="tag">access-respecting collection</span><span class="tag">community recollection</span><span class="tag safe">freshness decay</span></div></div><div class="source-item"><strong>Other public web sources</strong><div class="tags"><span class="tag">robots / terms respected</span><span class="tag">license review</span><span class="tag">source URL + timestamp</span></div></div><div class="safety"><b>Important:</b> Candidate-reported prompts can be incomplete or wrong. This app must not claim they are authentic, current, confidential, or leaked. Exclude paywalled, private, restricted, or copyright-sensitive content; store short metadata and a citation instead of copied posts.</div><p><b>Production pipeline:</b> scheduled public-source discovery → permission and license filter → dedupe & topical clustering → freshness/confidence scoring → human review queue → question templates with citations.</p></section></div>`)}
function render(){ if(state.view==='home')home();else if(state.view==='interview') {app.innerHTML=interviewer();startTimer()}else app.innerHTML=report() }
function startTimer(){clearInterval(timer);timer=setInterval(()=>{state.seconds--;if(state.seconds<=0){state.seconds=0;clearInterval(timer)}const el=document.querySelector('.timer');if(el){el.textContent=`${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`;if(state.seconds<300)el.classList.add('warn')}},1000)}
app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='sources'){sources();return}if(action==='close'){e.target.closest('.modal-backdrop').remove();return}if(action==='home'||action==='restart'){state.view='home';render();return}if(action==='start'){state.company=document.querySelector('#company').value;state.role=document.querySelector('#role').value;state.level=document.querySelector('#level').value;state.view='interview';state.round=0;state.followUp=false;state.seconds=rounds[0].duration*60;state.answers=[];render();return}if(action==='mic'){state.mic=!state.mic;render();return}if(action==='respond'){state.answers[state.round]=document.querySelector('#answer').value;if(!state.followUp){state.followUp=true;render()}else if(state.round<2){state.round++;state.followUp=false;state.seconds=rounds[state.round].duration*60;render()}else{state.view='report';render()}return}if(action==='end'){state.view='report';render()}});
render();
